from decimal import Decimal


def _value(record: dict | None, field: str):
    if not record:
        return ""
    return record.get(field, "")


def _nvl(value, default):
    return default if value is None or value == "" else value


def _number(value) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _numeric_equal(left, right) -> bool:
    return _number(left) == _number(right)


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amount = _value(record, "AMT")
    lost_reason = _value(record, "LOST_RSN")
    close_date = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amount, 0)) >= Decimal(0)):
            errors.append({
                "code": "E3001",
                "message": "Amount negative",
                "severity": "BLOCK",
            })

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _numeric_equal(_nvl(amount, 0), 0))):
            errors.append({
                "code": "E3002",
                "message": "Won opportunity requires amount",
                "severity": "BLOCK",
            })

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_reason == "")):
            errors.append({
                "code": "E3003",
                "message": "Lost reason required",
                "severity": "BLOCK",
            })

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and close_date == "00000000")):
            errors.append({
                "code": "E3004",
                "message": "Won opportunity requires close date",
                "severity": "BLOCK",
            })

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append({
                "code": "E3005",
                "message": "Cannot reopen a won opportunity",
                "severity": "BLOCK",
            })

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (stat_cd == "P" and _numeric_equal(stage_pct, 10))
            or (stat_cd == "Q" and _numeric_equal(stage_pct, 25))
            or (stat_cd == "N" and _numeric_equal(stage_pct, 60))
            or (stat_cd == "W" and _numeric_equal(stage_pct, 100))
            or (stat_cd == "L" and _numeric_equal(stage_pct, 0))
        )
        if not stage_consistent:
            errors.append({
                "code": "E3006",
                "message": "Stage percent inconsistent with status",
                "severity": "BLOCK",
            })

    # OPP-007
    if event == "INSERT":
        close_date_not_past = (
            close_date == "00000000"
            or (
                close_date != "00000000"
                and today != "00000000"
                and close_date >= today
            )
        )
        if not close_date_not_past:
            errors.append({
                "code": "E3007",
                "message": "Close date in past",
                "severity": "WARN",
            })

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
